package com.csust.eyediagnosis.workflow.persistence;
import com.csust.eyediagnosis.workflow.domain.WorkflowStatus; import com.csust.eyediagnosis.workflow.persistence.converter.WorkflowEnumConverter; import com.csust.eyediagnosis.workflow.persistence.exception.WorkflowPersistenceMappingException; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*;
class PersistenceEnumMappingTest { @Test void persistsEnumNamesAndRejectsUnknownDatabaseValues() { assertEquals("CREATED", WorkflowEnumConverter.toDatabase(WorkflowStatus.CREATED)); assertEquals(WorkflowStatus.CREATED, WorkflowEnumConverter.fromDatabase(WorkflowStatus.class, "CREATED")); assertThrows(WorkflowPersistenceMappingException.class, () -> WorkflowEnumConverter.fromDatabase(WorkflowStatus.class, "UNRECOGNIZED")); } }
